for i,(head,body) in enumerate(METHODS):
    if head=='AUC and conditional intensity errors':
        METHODS[i]=(head,
            'Global AUC in main Fig. 1a,b remains the original monthly spatial discrimination metric. '
            'Main Fig. 1c instead pools raw cell-month samples within an 11 × 11 array of 1° ocean grid cells '
            '(centre ±5 grid centres), restricted to the same major ocean basin and 60°S–60°N. Longitude wraps periodically. '
            'The primary window is April of the event year through September of the next year (18 months). '
            'Forecast records from the original July–June window are reused without modification; additional months use '
            'the same archived reader. Neighbour cells must have complete paired records for all events and leads. '
            'For each event and lead, weighted ROC AUC ranks forecast SST minus its local calendar-month Q90 against '
            'observed SST above Q90, with cosine-latitude sample weights and half credit for ties. '
            'A pool with only one observed class is undefined. Canonical-minus-target differences use equal weights '
            'for the two historical events and nine leads; only centres with all 27 finite AUCs enter the map. '
            'No interpolation or smoothing of the computed AUC is applied. Overlapping neighbourhoods reduce effective '
            'spatial independence despite the unchanged 1° output grid. Figure 17 separately checks 12 versus 18 months and '
            'single-cell versus 11° support. Forecast/observed intensity is max(SST − Q90,0); squared errors are pooled on '
            'observed-MHW samples only, using the same neighbourhood and time support. Roots follow MSE aggregation, '
            'including equal-event canonical averaging and region averaging. Regional neighbourhood metrics cannot '
            'be summed to recover the original global AUC gap. No claim of increased independent sample size is made.')
    elif head=='Scope of the supplementary analyses':
        METHODS[i]=(head,body.replace('Figures 1–4 and 16','Figures 1–4 and 16–17'))
COVERAGE[0]=('S1, S16–S17','SST; conditional intensity RMSE; pooled temporal AUC',
    'ERSST + retained four-model SST extraction','Q90:1985–2014; maps:April–September next year; S17 also July–June',
    'Ocean ≤60°; same-basin 11° neighbourhood; inset masks ±20°',
    'S1a:10 events; S1b:404 months; maps:3 events ×18 months ×9 leads',
    'Lead labels 1–9; single-class/invalid pools missing; original extraction limits retained')
